// src/features/clients/components/ClientCredentialsModal.jsx
import { useState } from 'react';
import type { ClientCredentials } from '../clientsSlice';
import { 
  Key, 
  Copy, 
  Check, 
  AlertTriangle,
  Download,
  Eye,
  EyeOff
} from 'lucide-react';
import { Modal, Button, Alert } from '../../../components';

const ClientCredentialsModal = ({ credentials, onClose }: { credentials: ClientCredentials; onClose: () => void }) => {
  const [copiedClientId, setCopiedClientId] = useState(false);
  const [copiedClientKey, setCopiedClientKey] = useState(false);
  const [showClientKey, setShowClientKey] = useState(false);
  const [downloaded, setDownloaded] = useState(false);

  const handleCopy = async (text: string, type: string) => {
    try {
      await navigator.clipboard.writeText(text);
      if (type === 'clientId') {
        setCopiedClientId(true);
        setTimeout(() => setCopiedClientId(false), 2000);
      } else {
        setCopiedClientKey(true);
        setTimeout(() => setCopiedClientKey(false), 2000);
      }
    } catch (error) {
      console.error('Failed to copy:', error);
    }
  };

  const handleDownload = () => {
    const content = `Client Credentials:
=====================
Client ID: ${credentials.clientId}
Client Key: ${credentials.clientKey}

Important Information:
- Store these credentials securely
- The client key cannot be retrieved again
- Keep this information confidential
- Use in your application's configuration`;

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `client-credentials-${credentials.clientId}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    setDownloaded(true);
    setTimeout(() => setDownloaded(false), 3000);
  };

  return (
    <Modal
      isOpen={true}
      onClose={onClose}
      size="md"
      title="Client Credentials"
      preventClose={true}
    >
      <div className="space-y-6">
        {/* Warning Alert */}
        <Alert
          type="warning"
          title="Important Security Notice"
          message="Store these credentials securely. The client key will not be shown again."
          showIcon
        />

        {/* Client ID */}
        <div className="space-y-2">
          <label className="text-sm font-medium text-gray-700 dark:text-gray-300">
            Client ID
          </label>
          <div className="relative">
            <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg">
              <code className="text-sm font-mono text-gray-900 dark:text-white break-all">
                {credentials.clientId}
              </code>
              <button
                onClick={() => handleCopy(credentials.clientId, 'clientId')}
                className="ml-2 p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg flex-shrink-0"
                title="Copy to clipboard"
              >
                {copiedClientId ? (
                  <Check className="w-5 h-5 text-green-500" />
                ) : (
                  <Copy className="w-5 h-5" />
                )}
              </button>
            </div>
          </div>
        </div>

        {/* Client Key */}
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <label className="text-sm font-medium text-gray-700 dark:text-gray-300">
              Client Key
            </label>
            <button
              onClick={() => setShowClientKey(!showClientKey)}
              className="text-sm text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300 flex items-center"
            >
              {showClientKey ? (
                <>
                  <EyeOff className="w-4 h-4 mr-1" />
                  Hide
                </>
              ) : (
                <>
                  <Eye className="w-4 h-4 mr-1" />
                  Show
                </>
              )}
            </button>
          </div>
          
          <div className="relative">
            <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg">
              <code className="text-sm font-mono text-gray-900 dark:text-white break-all">
                {showClientKey ? credentials.clientKey : '•'.repeat(32)}
              </code>
              <button
                onClick={() => handleCopy(credentials.clientKey, 'clientKey')}
                className="ml-2 p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg flex-shrink-0"
                title="Copy to clipboard"
              >
                {copiedClientKey ? (
                  <Check className="w-5 h-5 text-green-500" />
                ) : (
                  <Copy className="w-5 h-5" />
                )}
              </button>
            </div>
          </div>
          
          <p className="text-xs text-gray-500 dark:text-gray-400">
            This key will not be shown again. Make sure to copy it now.
          </p>
        </div>

        {/* Download Section */}
        <div className="border-t border-gray-200 dark:border-gray-700 pt-6">
          <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
            <div className="flex items-start">
              <Key className="w-5 h-5 text-blue-500 mt-0.5 mr-3 flex-shrink-0" />
              <div className="text-sm text-blue-700 dark:text-blue-300">
                <p className="font-medium mb-1">Recommended Action</p>
                <p>Download these credentials and store them in a secure location. You will need them to configure your application.</p>
              </div>
            </div>
          </div>
          
          <div className="flex justify-center mt-4">
            <Button
              variant="primary"
              onClick={handleDownload}
              icon={Download}
              className="w-full"
            >
              {downloaded ? 'Downloaded!' : 'Download Credentials'}
            </Button>
          </div>
        </div>

        {/* Final Instructions */}
        <div className="bg-gray-50 dark:bg-gray-800/50 border border-gray-200 dark:border-gray-700 rounded-lg p-4">
          <h4 className="text-sm font-medium text-gray-900 dark:text-white mb-2">
            Next Steps:
          </h4>
          <ol className="text-sm text-gray-600 dark:text-gray-400 space-y-1 list-decimal list-inside">
            <li>Store the credentials in a secure location</li>
            <li>Configure your application with these credentials</li>
            <li>Test the authentication flow</li>
            <li>Contact support if you encounter any issues</li>
          </ol>
        </div>

        {/* Footer */}
        <div className="flex justify-center pt-6 border-t border-gray-200 dark:border-gray-700">
          <Button
            variant="primary"
            onClick={onClose}
            className="w-full"
          >
            I've Saved the Credentials
          </Button>
        </div>
      </div>
    </Modal>
  );
};

export default ClientCredentialsModal;

// src/features/clients/components/ClientDetailsModal.jsx
import { useState, useEffect, useCallback } from 'react';
import type { Client } from '../../../types';
import { useAppDispatch } from '../../../app/hooks';
import { fetchClientDetails } from '../clientsSlice';
import {
  X,
  Building,
  Globe,
  Clock,
  Users,
  Activity,
  Key,
  Shield,
  Calendar,
  Copy,
  Download
} from 'lucide-react';
import { Modal, Badge, Button, LoadingSpinner } from '../../../components';
import { formatDate } from '../../../utils/helpers';

const ClientDetailsModal = ({ clientId, onClose }: { clientId: string; onClose: () => void }) => {
  const dispatch = useAppDispatch();
  const [loading, setLoading] = useState(true);
  const [client, setClient] = useState<Client | null>(null);
  const [activeTab, setActiveTab] = useState('overview');
  const [copied, setCopied] = useState(false);

  const loadClientDetails = useCallback(async () => {
    setLoading(true);
    try {
      const result = await dispatch(fetchClientDetails(clientId)).unwrap();
      setClient(result);
    } catch (error) {
      console.error('Failed to load client details:', error);
    } finally {
      setLoading(false);
    }
  }, [dispatch, clientId]);

  useEffect(() => { void loadClientDetails(); }, [loadClientDetails]);

  const handleCopy = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (error) {
      console.error('Failed to copy:', error);
    }
  };

  const handleDownloadConfig = () => {
    if (!client) return;

    const config = {
      clientId: client.clientId,
      name: client.name,
      description: client.description,
      allowedOrigins: client.allowedOrigins,
      idleTimeout: client.idleTimeout,
      createdAt: client.createdAt,
      status: client.status,
    };

    const content = JSON.stringify(config, null, 2);
    const blob = new Blob([content], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `client-config-${client.clientId}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const tabs = [
    { id: 'overview', label: 'Overview', icon: Building },
    { id: 'security', label: 'Security', icon: Shield },
    { id: 'activity', label: 'Activity', icon: Activity },
    { id: 'config', label: 'Configuration', icon: Key },
  ];

  if (loading || !client) {
    return (
      <Modal isOpen={true} onClose={onClose} size="lg">
        <div className="py-12">
          <LoadingSpinner text="Loading client details..." />
        </div>
      </Modal>
    );
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'ACTIVE': return 'success' as const;
      case 'INACTIVE': return 'error' as const;
      case 'PENDING': return 'warning' as const;
      case 'SUSPENDED': return 'warning' as const;
      default: return 'default' as const;
    }
  };

  return (
    <Modal
      isOpen={true}
      onClose={onClose}
      size="xl"
      title={
        <div className="flex items-center">
          <Building className="w-6 h-6 mr-3 text-blue-500" />
          <div>
            <h2 className="text-xl font-bold text-gray-900 dark:text-white">
              {client.name}
            </h2>
            <p className="text-sm text-gray-600 dark:text-gray-400">
              Client ID: {client.clientId}
            </p>
          </div>
        </div>
      }
    >
      <div className="space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <Badge
            variant={getStatusColor(client.status)}
            size="lg"
          >
            {client.status}
          </Badge>
          
          <div className="flex items-center space-x-2">
            <Button
              variant="outline"
              size="sm"
              onClick={handleDownloadConfig}
              icon={Download}
            >
              Config
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleCopy(client.clientId)}
              icon={Copy}
            >
              {copied ? 'Copied!' : 'Copy ID'}
            </Button>
          </div>
        </div>

        {/* Tabs */}
        <div className="border-b border-gray-200 dark:border-gray-700">
          <nav className="-mb-px flex space-x-8">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`py-2 px-1 border-b-2 font-medium text-sm flex items-center ${
                  activeTab === tab.id
                    ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                    : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
                }`}
              >
                <tab.icon className="w-4 h-4 mr-2" />
                {tab.label}
              </button>
            ))}
          </nav>
        </div>

        {/* Content */}
        <div className="space-y-6">
          {/* Overview Tab */}
          {activeTab === 'overview' && (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <div className="space-y-6">
                {/* Basic Info */}
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                    Basic Information
                  </h3>
                  <div className="space-y-3">
                    <div className="flex items-center justify-between">
                      <span className="text-gray-600 dark:text-gray-400">Name</span>
                      <span className="font-medium text-gray-900 dark:text-white">
                        {client.name}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-gray-600 dark:text-gray-400">Description</span>
                      <span className="font-medium text-gray-900 dark:text-white">
                        {client.description || 'No description'}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-gray-600 dark:text-gray-400">Created</span>
                      <span className="font-medium text-gray-900 dark:text-white">
                        {formatDate(client.createdAt)}
                      </span>
                    </div>
                  </div>
                </div>

                {/* Stats */}
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                    Statistics
                  </h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-4 text-center">
                      <Users className="w-8 h-8 text-blue-500 mx-auto mb-2" />
                      <p className="text-2xl font-bold text-gray-900 dark:text-white">
                        {client.userCount || 0}
                      </p>
                      <p className="text-sm text-gray-600 dark:text-gray-400">Users</p>
                    </div>
                    <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-4 text-center">
                      <Activity className="w-8 h-8 text-green-500 mx-auto mb-2" />
                      <p className="text-2xl font-bold text-gray-900 dark:text-white">
                        {client.sessionCount || 0}
                      </p>
                      <p className="text-sm text-gray-600 dark:text-gray-400">Active Sessions</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Allowed Origins */}
              <div>
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                  Allowed Origins
                </h3>
                <div className="space-y-2">
                  {client.allowedOrigins?.map((origin, index) => (
                    <div
                      key={index}
                      className="flex items-center p-3 bg-gray-50 dark:bg-gray-800 rounded-lg"
                    >
                      <Globe className="w-4 h-4 text-gray-400 mr-3 flex-shrink-0" />
                      <span className="text-sm text-gray-900 dark:text-white break-all">
                        {origin}
                      </span>
                    </div>
                  ))}
                  
                  {(!client.allowedOrigins || client.allowedOrigins.length === 0) && (
                    <p className="text-gray-500 dark:text-gray-400 text-center py-4">
                      No origins configured
                    </p>
                  )}
                </div>

                {/* Timeout Setting */}
                <div className="mt-6">
                  <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                    Session Settings
                  </h3>
                  <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-800 rounded-lg">
                    <div className="flex items-center">
                      <Clock className="w-5 h-5 text-gray-400 mr-3" />
                      <div>
                        <p className="text-sm font-medium text-gray-900 dark:text-white">
                          Idle Timeout
                        </p>
                        <p className="text-sm text-gray-600 dark:text-gray-400">
                          Session expires after inactivity
                        </p>
                      </div>
                    </div>
                    <span className="text-lg font-bold text-blue-600 dark:text-blue-400">
                      {client.idleTimeout || 30} min
                    </span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Security Tab */}
          {activeTab === 'security' && (
            <div className="space-y-6">
              <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-6">
                <div className="flex items-start">
                  <Shield className="w-6 h-6 text-blue-500 mr-3 flex-shrink-0 mt-0.5" />
                  <div>
                    <h3 className="text-lg font-semibold text-blue-800 dark:text-blue-300 mb-2">
                      Security Configuration
                    </h3>
                    <p className="text-blue-700 dark:text-blue-400">
                      This client is configured with OAuth 2.0 authentication flow.
                      All API calls require valid client credentials and user tokens.
                    </p>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <h4 className="text-md font-semibold text-gray-900 dark:text-white mb-3">
                    Authentication Methods
                  </h4>
                  <ul className="space-y-2">
                    <li className="flex items-center">
                      <div className="w-2 h-2 bg-green-500 rounded-full mr-3"></div>
                      <span className="text-gray-700 dark:text-gray-300">OAuth 2.0 Authorization Code</span>
                    </li>
                    <li className="flex items-center">
                      <div className="w-2 h-2 bg-green-500 rounded-full mr-3"></div>
                      <span className="text-gray-700 dark:text-gray-300">JWT Token Based</span>
                    </li>
                    <li className="flex items-center">
                      <div className="w-2 h-2 bg-green-500 rounded-full mr-3"></div>
                      <span className="text-gray-700 dark:text-gray-300">Refresh Token Rotation</span>
                    </li>
                  </ul>
                </div>

                <div>
                  <h4 className="text-md font-semibold text-gray-900 dark:text-white mb-3">
                    Security Policies
                  </h4>
                  <ul className="space-y-2">
                    <li className="flex items-center">
                      <div className="w-2 h-2 bg-green-500 rounded-full mr-3"></div>
                      <span className="text-gray-700 dark:text-gray-300">Rate Limiting Enabled</span>
                    </li>
                    <li className="flex items-center">
                      <div className="w-2 h-2 bg-green-500 rounded-full mr-3"></div>
                      <span className="text-gray-700 dark:text-gray-300">IP Based Restrictions</span>
                    </li>
                    <li className="flex items-center">
                      <div className="w-2 h-2 bg-green-500 rounded-full mr-3"></div>
                      <span className="text-gray-700 dark:text-gray-300">CORS Policy Enforced</span>
                    </li>
                  </ul>
                </div>
              </div>
            </div>
          )}

          {/* Activity Tab */}
          {activeTab === 'activity' && (
            <div>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                Recent Activity
              </h3>
              <div className="space-y-4">
                {[
                  { event: 'User Registration', count: 45, change: '+12%' },
                  { event: 'Successful Logins', count: 1289, change: '+8%' },
                  { event: 'Failed Attempts', count: 23, change: '-5%' },
                  { event: 'Token Refreshes', count: 567, change: '+15%' },
                ].map((stat, index) => (
                  <div
                    key={index}
                    className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-800 rounded-lg"
                  >
                    <div>
                      <p className="font-medium text-gray-900 dark:text-white">
                        {stat.event}
                      </p>
                      <p className="text-sm text-gray-600 dark:text-gray-400">
                        Last 24 hours
                      </p>
                    </div>
                    <div className="text-right">
                      <p className="text-2xl font-bold text-gray-900 dark:text-white">
                        {stat.count.toLocaleString()}
                      </p>
                      <p className={`text-sm ${
                        stat.change.startsWith('+') 
                          ? 'text-green-600 dark:text-green-400'
                          : 'text-red-600 dark:text-red-400'
                      }`}>
                        {stat.change} from yesterday
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Configuration Tab */}
          {activeTab === 'config' && (
            <div>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                Client Configuration
              </h3>
              
              <div className="bg-gray-900 rounded-lg p-6">
                <div className="flex items-center justify-between mb-4">
                  <div className="flex items-center">
                    <Key className="w-5 h-5 text-gray-400 mr-2" />
                    <span className="text-gray-300 font-medium">Configuration JSON</span>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleDownloadConfig}
                    icon={Download}
                  >
                    Download
                  </Button>
                </div>
                
                <pre className="text-gray-300 text-sm overflow-x-auto">
                  {JSON.stringify({
                    client: {
                      id: client.clientId,
                      name: client.name,
                      description: client.description,
                      status: client.status,
                      createdAt: client.createdAt,
                    },
                    security: {
                      allowedOrigins: client.allowedOrigins,
                      idleTimeout: client.idleTimeout,
                      authentication: "OAuth 2.0",
                      tokenType: "JWT",
                    },
                    endpoints: {
                      authorization: `${window.location.origin}/oauth/authorize`,
                      token: `${window.location.origin}/oauth/token`,
                      userInfo: `${window.location.origin}/oauth/userinfo`,
                    },
                  }, null, 2)}
                </pre>
              </div>

              <div className="mt-6 grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-4">
                  <h4 className="font-medium text-gray-900 dark:text-white mb-2">
                    Integration Steps
                  </h4>
                  <ol className="text-sm text-gray-600 dark:text-gray-400 space-y-2 list-decimal list-inside">
                    <li>Configure OAuth client in your application</li>
                    <li>Set redirect URIs to match allowed origins</li>
                    <li>Implement authorization code flow</li>
                    <li>Handle token storage and refresh</li>
                  </ol>
                </div>
                
                <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-4">
                  <h4 className="font-medium text-gray-900 dark:text-white mb-2">
                    API Usage Example
                  </h4>
                  <code className="text-sm bg-gray-900 text-gray-300 p-2 rounded block">
                    {`// Initialize OAuth client
const client = new OAuth2Client({
  clientId: '${client.clientId}',
  authorizationEndpoint: '${window.location.origin}/oauth/authorize',
  tokenEndpoint: '${window.location.origin}/oauth/token'
});`}
                  </code>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex justify-between items-center pt-6 border-t border-gray-200 dark:border-gray-700">
          <Button
            variant="outline"
            onClick={onClose}
          >
            Close
          </Button>
          <div className="flex items-center space-x-2">
            <Button
              variant="outline"
              onClick={() => {
                // Handle edit
                onClose();
              }}
            >
              Edit Client
            </Button>
            <Button
              variant={client.status === 'ACTIVE' ? 'warning' : 'success'}
              onClick={() => {
                // Handle status toggle
                onClose();
              }}
            >
              {client.status === 'ACTIVE' ? 'Deactivate' : 'Activate'}
            </Button>
          </div>
        </div>
      </div>
    </Modal>
  );
};

export default ClientDetailsModal;
